1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.List;
4	
5	/**
6	 * Formats a stored E.164 telephone for humans: the country code, a space, then the
7	 * national digits grouped in threes (e.g. '+61412345678' -> '+61 412 345 678').
8	 */
9	public final class TelephoneFormatter {
10	
11	    private TelephoneFormatter() {
12	    }
13	
14	    /** Known country codes, longest first, so the national number can be split off. */
15	    private static final List<String> COUNTRY_CODES = List.of("61", "1");
16	
17	    public static String display(String e164) {
18	        if (e164 == null || !e164.startsWith("+")) {
19	            return e164;
20	        }
21	        String digits = e164.substring(1);
22	        String code = COUNTRY_CODES.stream().filter(digits::startsWith).findFirst()
23	            .orElse(digits.substring(0, 1));
24	        String national = digits.substring(code.length()).replaceAll("(\\d{3})(?=\\d)", "$1 ");
25	        return "+" + code + " " + national;
26	    }
27	}
