61	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
62	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
63	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
64	     * the '+', else the number is rejected as invalid.
65	     */
66	    @Named("normalizeTelephone")
67	    default String normalizeTelephone(String telephone) {
68	        if (telephone == null) {
69	            return null;
70	        }
71	        boolean international = telephone.trim().startsWith("+");
72	        String digits = telephone.replaceAll("\\D", "");
73	        if (!international) {
74	            if (digits.startsWith("0")) {
75	                digits = digits.substring(1);
76	            }
77	            digits = "61" + digits;
78	        }
79	        if (digits.length() < 8 || digits.length() > 15) {
80	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
81	        }
